package com.example.demo;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class GreetingServiceTest {

    @Mock
    private GreetingRepository greetingRepository;

    @Test
    void greetsUsingTheRepositoryResult() {
        when(greetingRepository.findGreetingFor("World")).thenReturn("Hello, World!");

        GreetingService greetingService = new GreetingService(greetingRepository);

        assertThat(greetingService.greet("World")).isEqualTo("Hello, World!");
    }

}

